first_accepted_patch:
--- a/rtl/fsm_controller.v
+++ b/rtl/fsm_controller.v
@@ -36,7 +36,7 @@
     // Sequential state transition and interval counter
     always @(posedge clk or negedge reset_n) begin
-        if (reset_n) begin
+        if (!reset_n) begin
             current_state <= S_MAIN_GREEN;
             timer_cnt     <= 4'd0;
         end else begin

